"use client";

import { type FormEvent, useEffect, useMemo, useState } from "react";
import { Activity, Archive, Boxes, Building2, ChevronDown, CircleUserRound, ClipboardCheck, Database, FileClock, Filter, LayoutDashboard, Menu, Monitor, Network, PackagePlus, Search, Server, Settings, ShieldCheck, Smartphone, UserCog, Users, Wifi, X } from "lucide-react";

type AssetView={id:string;name:string;meta:string;code:string;category:string;group:"OFFICE"|"NETWORK";place:string;status:string;updatedAt:string};
export type DashboardSummary={activeAssignments:number|null;totalAssets:number|null;networkAssets:number|null;attentionAssets:number|null;unmatchedAd:number;adSyncStatus:"NEVER"|"RUNNING"|"COMPLETED"|"PARTIAL"|"FAILED";adSyncAt:string|null;adSyncFailed:number;siteLatencyMs:number|null};
const statusLabel:Record<string,string>={DRAFT:"Taslak",IN_STOCK:"Stokta",IN_USE:"Kullanımda",MAINTENANCE:"Bakımda",RETIRED:"Kullanım dışı",LOST:"Kayıp",ARCHIVED:"Arşiv"};
const nav = [
  ["Genel", [["Dashboard",LayoutDashboard],["Tüm Varlıklar",Boxes],["Kullanıcı Cihazları",Monitor],["Ağ & Altyapı",Network]]],
  ["Operasyon", [["Kabin Yönetimi",Server],["Personel",Users],["Aktif Zimmetler",ClipboardCheck],["Telefon Kullanıcıları",Smartphone]]],
  ["Yönetim", [["AD Senkronizasyonu",Activity],["Eşleşmeyen AD",Filter],["Kullanıcı & Yetki",UserCog],["Sahip Şirketler",Building2],["Veritabanı Sağlığı",Database],["Audit Log",FileClock],["Ayarlar",Settings]]],
] as const;

export function Dashboard({siteId,location,user,assets,online,summary}:{siteId:string;location:{site:string;province:string};user:{displayName:string;role:string};assets:AssetView[];online:boolean;summary:DashboardSummary}) {
  const [active,setActive]=useState("Dashboard"); const [query,setQuery]=useState(""); const [attentionOnly,setAttentionOnly]=useState(false); const [menuOpen,setMenuOpen]=useState(false);
  const canWrite=user.role==="ADMIN"||user.role==="IT_OPERATOR";
  const openNewAsset=()=>{setActive("Tüm Varlıklar");setMenuOpen(false)};
  const filtered=useMemo(()=>assets.filter(asset=>`${asset.name} ${asset.code} ${asset.category}`.toLocaleLowerCase("tr").includes(query.toLocaleLowerCase("tr"))&&(!attentionOnly||asset.status==="MAINTENANCE"||asset.status==="LOST")),[assets,query,attentionOnly]);
  const recentAssets=filtered.slice(0,8);
  const adStatusLabel={NEVER:"Başlatılmadı",RUNNING:"Çalışıyor",COMPLETED:"Başarılı",PARTIAL:"Kısmi",FAILED:"Başarısız"}[summary.adSyncStatus];
  const adWarn=summary.adSyncStatus==="NEVER"||summary.adSyncStatus==="PARTIAL"||summary.adSyncStatus==="FAILED";
  return <div className={`shell role-${user.role.toLocaleLowerCase("tr")}`}>
    {menuOpen&&<button className="sidebar-backdrop" aria-label="Menüyü kapat" onClick={()=>setMenuOpen(false)}/>}<aside className={`sidebar ${menuOpen?"open":""}`}><div className="brand"><div className="brand-mark">E</div><span><strong>Envantra</strong><small>DİLER HOLDİNG</small></span></div>
      {nav.map(([title,items])=>{const visible=items.filter(([label])=>canNavigate(user.role,label));return visible.length?<div key={title}><div className="nav-title">{title}</div>{visible.map(([label,Icon])=><button key={label} className={`nav-item ${active===label?"active":""}`} onClick={()=>{setMenuOpen(false);if(label==="Dashboard"){window.location.reload();return}setActive(label)}}><Icon/><span>{label}</span></button>)}</div>:null})}
      <div className="sidebar-user"><div className="avatar">{initials(user.displayName)}</div><div><strong>{user.displayName}</strong><small>{roleLabel[user.role]??user.role}</small></div></div>
    </aside>
    <main className="main"><header className="topbar"><div className="crumb"><button className="icon-btn mobile-menu" aria-label="Menüyü aç" aria-expanded={menuOpen} onClick={()=>setMenuOpen(current=>!current)}><Menu size={17}/></button><Building2 size={16}/><span>{location.province}</span><span>/</span><strong>{location.site}</strong><button className="icon-btn" aria-label="Lokasyon değiştir" title="Lokasyon değiştir" onClick={()=>{window.location.href="/select"}}><ChevronDown size={14}/></button></div><div className="top-actions"><button className="icon-btn" aria-label="Oturumu kapat" title="Oturumu kapat" onClick={async()=>{await fetch("/api/auth/logout",{method:"POST"});window.location.href="/login"}}><CircleUserRound size={17}/></button>{canWrite&&<button className="primary" onClick={openNewAsset}><PackagePlus size={15}/> Yeni varlık</button>}</div></header>
      <div className="content"><div className="page-title"><div><div className="eyebrow">Operasyon merkezi</div><h1>{active}</h1><p>{location.site} lokasyonundaki BT varlıklarının güncel görünümü</p></div><button className="location-pill" onClick={()=>{window.location.href="/select"}} aria-label="Lokasyon değiştir"><span className="live-dot" style={{background:online?undefined:"#d98213"}}/><span><strong>{location.site}</strong><br/><small>Veritabanı {online?"çevrimiçi":"çevrimdışı"}</small></span><ChevronDown size={15}/></button></div>
        {active==="Dashboard"?<><section className="stats"><Stat label="Toplam varlık" value={summary.totalAssets===null?"—":String(summary.totalAssets)} detail={summary.totalAssets===null?"Veritabanı erişilemiyor":"Seçili lokasyon"} Icon={Boxes}/><Stat label="Aktif zimmet" value={summary.activeAssignments===null?"—":String(summary.activeAssignments)} detail={summary.activeAssignments===null?"Veritabanı erişilemiyor":"Güncel aktif kayıt"} Icon={ClipboardCheck}/><Stat label="Ağ cihazı" value={summary.networkAssets===null?"—":String(summary.networkAssets)} detail={summary.networkAssets===null?"Veritabanı erişilemiyor":"Güncel envanter"} Icon={Wifi}/><Stat label="Bakım / arıza" value={summary.attentionAssets===null?"—":String(summary.attentionAssets)} detail={summary.attentionAssets===null?"Veritabanı erişilemiyor":"Bakımda veya kayıp"} Icon={Archive}/></section>
        <div className="grid"><section className="panel"><div className="panel-head"><div><h2>Son güncellenen varlıklar</h2><p>Güncellenme tarihine göre en yeni 8 kayıt</p></div><button className="link-button" onClick={()=>setActive("Tüm Varlıklar")}>Tümünü görüntüle →</button></div><div className="search-row"><div className="search"><Search/><input aria-label="Varlık ara" placeholder="Cihaz adı, kod veya kategori ara…" value={query} onChange={e=>setQuery(e.target.value)}/></div><button className="filter" aria-pressed={attentionOnly} onClick={()=>setAttentionOnly(current=>!current)}><Filter size={12}/>{attentionOnly?"Filtreyi kaldır":"Bakım / kayıp"}</button></div><div className="table-wrap"><table><thead><tr><th>Varlık</th><th>Varlık kodu</th><th>Kategori</th><th>Konum</th><th>Güncelleme</th><th>Durum</th></tr></thead><tbody>{recentAssets.map(a=>{const Icon=a.group==="NETWORK"?Network:Monitor;const tone=a.status==="MAINTENANCE"||a.status==="LOST"?"amber":a.status==="IN_USE"?"green":"gray";return <tr key={a.code}><td><div className="asset-name"><span className="device-icon"><Icon size={15}/></span><span><strong>{a.name}</strong><small>{a.meta}</small></span></div></td><td className="code">{a.code}</td><td>{a.category}</td><td>{a.place}</td><td>{formatCell(a.updatedAt)}</td><td><span className={`badge ${tone}`}>{statusLabel[a.status]??a.status}</span></td></tr>})}</tbody></table></div></section>
          <aside><section className="panel"><div className="panel-head"><div><h2>Lokasyon sağlığı</h2><p>Canlı bağlantı ve senkronizasyon durumu</p></div><ShieldCheck size={18} color={online&&!adWarn?"#168c62":"#bc6500"}/></div><div className="health-list"><Health name="Lokasyon veritabanı" detail={online?"Bağlantı doğrulandı":"Bağlantı kurulamadı"} value={online?(summary.siteLatencyMs===null?"Çevrimiçi":`${summary.siteLatencyMs} ms`):"Çevrimdışı"} warn={!online}/><Health name="AD senkronizasyonu" detail={summary.adSyncAt?`Son çalışma: ${formatCell(summary.adSyncAt)}`:"Henüz senkronizasyon yapılmadı"} value={summary.adSyncFailed?`${adStatusLabel} · ${summary.adSyncFailed} hata`:adStatusLabel} warn={adWarn}/><Health name="Eşleşmeyen AD kaydı" detail={summary.unmatchedAd?"Lokasyon eşleştirmesi bekleniyor":"Bekleyen kayıt bulunmuyor"} value={String(summary.unmatchedAd)} warn={summary.unmatchedAd>0}/></div></section>
          <section className="panel" style={{marginTop:18}}><div className="panel-head"><div><h2>Hızlı işlemler</h2><p>Sık kullanılan kayıt işlemleri</p></div></div><div className="quick-grid"><button className="quick" onClick={openNewAsset}><PackagePlus/>Varlık ekle</button><button className="quick" onClick={()=>setActive("Aktif Zimmetler")}><ClipboardCheck/>Zimmet oluştur</button><button className="quick" onClick={()=>setActive("Personel")}><Users/>Personel bul</button><button className="quick" onClick={()=>setActive("Kabin Yönetimi")}><Server/>Kabin görüntüle</button></div></section></aside>
        </div></>:<OperationalView active={active} siteId={siteId} assets={assets}/>}</div></main></div>;
}
function Stat({label,value,detail,Icon}:{label:string;value:string;detail:string;Icon:typeof Boxes}){return <article className="stat"><div className="stat-head"><span>{label}</span><span className="stat-icon"><Icon size={15}/></span></div><strong>{value}</strong><div className={detail.includes("kritik")?"trend muted":"trend"}>{detail}</div></article>}
function Health({name,detail,value,warn=false}:{name:string;detail:string;value:string;warn?:boolean}){return <div className="health-item"><div className={`health-icon ${warn?"warn":""}`}><Database size={15}/></div><div className="health-info"><strong>{name}</strong><span>{detail}</span></div><span className="latency" style={{color:warn?"#b86500":undefined}}>{value}</span></div>}

type RemoteRow=Record<string,unknown>;type Column={key:string;label:string};
const remoteConfig:Record<string,{endpoint:string;columns:Column[];pick?:string}>={
  "Personel":{endpoint:"/api/personnel",columns:[{key:"displayName",label:"Ad soyad"},{key:"department",label:"Departman"},{key:"title",label:"Unvan"},{key:"email",label:"E-posta"},{key:"isActive",label:"Durum"}]},
  "Aktif Zimmetler":{endpoint:"/api/assignments",columns:[{key:"assetCode",label:"Varlık kodu"},{key:"assetName",label:"Varlık"},{key:"profileName",label:"Personel"},{key:"assignedAt",label:"Zimmet tarihi"},{key:"status",label:"Durum"}]},
  "Telefon Kullanıcıları":{endpoint:"/api/phone-users",columns:[{key:"assetCode",label:"Varlık kodu"},{key:"assetName",label:"Telefon"},{key:"profileName",label:"Kullanıcı"},{key:"extension",label:"Dahili"},{key:"isActive",label:"Durum"}]},
  "Kabin Yönetimi":{endpoint:"/api/admin/locations",pick:"racks",columns:[{key:"number",label:"Kabin no"},{key:"name",label:"Kabin adı"},{key:"shortCode",label:"Kısa kod"},{key:"roomId",label:"Oda"},{key:"isActive",label:"Durum"}]},
  "Veritabanı Sağlığı":{endpoint:"/api/health/sites",columns:[{key:"name",label:"Lokasyon"},{key:"status",label:"Durum"},{key:"latencyMs",label:"Gecikme (ms)"},{key:"lastSuccessAt",label:"Son başarılı bağlantı"},{key:"lastFailureAt",label:"Son hata"},{key:"errorCode",label:"Hata kodu"}]},
  "Audit Log":{endpoint:"/api/audit",columns:[{key:"createdAt",label:"Tarih"},{key:"action",label:"İşlem"},{key:"entityType",label:"Kayıt türü"},{key:"entityId",label:"Kayıt"},{key:"source",label:"Kaynak"}]},
  "Ayarlar":{endpoint:"/api/admin/categories",columns:[{key:"group",label:"Ana grup"},{key:"name",label:"Kategori"},{key:"code",label:"Kod"},{key:"formKind",label:"Form"},{key:"isActive",label:"Durum"}]},
};
function OperationalView({active,siteId,assets}:{active:string;siteId:string;assets:AssetView[]}){const assetView=active==="Tüm Varlıklar"||active==="Kullanıcı Cihazları"||active==="Ağ & Altyapı";const shown=assetView?assets.filter(a=>active==="Kullanıcı Cihazları"?a.group==="OFFICE":active==="Ağ & Altyapı"?a.group==="NETWORK":true):[];const [rows,setRows]=useState<RemoteRow[]>([]);const [state,setState]=useState<"loading"|"ready"|"error">("loading");const [dialog,setDialog]=useState<"assignment"|"phone">();const [term,setTerm]=useState("");const [page,setPage]=useState(1);const config=remoteConfig[active];useEffect(()=>{if(assetView||!config)return;const controller=new AbortController();const loadingTimer=window.setTimeout(()=>setState("loading"),0);const separator=config.endpoint.includes("?")?"&":"?";const needsSite=["/api/assignments","/api/phone-users","/api/audit"].includes(config.endpoint);fetch(`${config.endpoint}${needsSite?`${separator}siteId=${siteId}`:""}`,{signal:controller.signal}).then(async response=>{if(!response.ok)throw new Error("İstek başarısız");const payload=await response.json() as {data?:unknown};let data=payload.data;if(config.pick&&data&&typeof data==="object"&&!Array.isArray(data))data=(data as RemoteRow)[config.pick];setRows(Array.isArray(data)?data.filter((item):item is RemoteRow=>typeof item==="object"&&item!==null):[]);setState("ready")}).catch(error=>{if(error instanceof Error&&error.name!=="AbortError")setState("error")});return()=>{window.clearTimeout(loadingTimer);controller.abort()}},[active,assetView,config,siteId]);if(active==="AD Senkronizasyonu")return <ActionPanel siteId={siteId}/>;if(active==="Eşleşmeyen AD")return <AdUnmatchedPanel/>;if(active==="Kullanıcı & Yetki")return <UserAccessPanel/>;if(active==="Sahip Şirketler")return <CompanyAdminPanel/>;if(active==="Ayarlar")return <CategoryAdminPanel/>;if(active==="Kabin Yönetimi")return <LocationAdminPanel/>;if(assetView)return <AssetPanel siteId={siteId} assets={shown}/>;if(!config)return <Empty title="Bu bölüm hazırlanıyor"/>;const createKind=active==="Aktif Zimmetler"?"assignment":active==="Telefon Kullanıcıları"?"phone":undefined;const actionable=active==="Aktif Zimmetler"||active==="Telefon Kullanıcıları";const filteredRows=rows.filter(row=>JSON.stringify(row).toLocaleLowerCase("tr").includes(term.toLocaleLowerCase("tr")));const visible=filteredRows.slice((page-1)*20,page*20);async function closeRecord(row:RemoteRow){const id=String(row.id??"");if(!id)return;const assignment=active==="Aktif Zimmetler";const response=await fetch(assignment?`/api/assignments/${id}/return`:`/api/phone-users/${id}/close`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({siteId})});if(response.ok)setRows(current=>assignment?current.filter(item=>item.id!==row.id):current.map(item=>item.id===row.id?{...item,isActive:false,endDate:new Date().toISOString().slice(0,10)}:item))}return <><section className="panel"><div className="panel-head"><div><h2>{active}</h2><p>{filteredRows.length} kayıt görüntüleniyor</p></div><div className="panel-actions"><button className="filter" onClick={()=>downloadCsv(active,filteredRows)}>CSV dışa aktar</button>{createKind&&<button className="primary" onClick={()=>setDialog(createKind)}><PackagePlus size={14}/> Yeni kayıt</button>}</div></div><div className="search-row"><div className="search"><Search/><input aria-label={`${active} içinde ara`} placeholder="Kayıtlarda ara…" value={term} onChange={e=>{setTerm(e.target.value);setPage(1)}}/></div></div>{state==="loading"?<Empty title="Kayıtlar yükleniyor…"/>:state==="error"?<Empty title="Veriler alınamadı"/>:visible.length===0?<Empty title="Henüz kayıt bulunmuyor"/>:<div className="table-wrap"><table><thead><tr>{config.columns.map(c=><th key={c.key}>{c.label}</th>)}{actionable&&<th>İşlem</th>}</tr></thead><tbody>{visible.map((row,index)=><tr key={String(row.id??index)}>{config.columns.map(c=><td key={c.key}>{formatCell(row[c.key])}</td>)}{actionable&&<td><button className="link-button" onClick={()=>closeRecord(row)}>{active==="Aktif Zimmetler"?"İade al":"Kullanıcıyı kapat"}</button></td>}</tr>)}</tbody></table></div>}<Pagination page={page} total={filteredRows.length} onPage={setPage}/></section>{dialog&&<RecordDialog kind={dialog} siteId={siteId} assets={assets} onClose={()=>setDialog(undefined)}/>}</>}
function AssetPanel({siteId,assets}:{siteId:string;assets:AssetView[]}){const [open,setOpen]=useState(false);const [selected,setSelected]=useState<AssetView>();const [term,setTerm]=useState("");const [page,setPage]=useState(1);const filtered=assets.filter(a=>`${a.code} ${a.name} ${a.category} ${a.meta}`.toLocaleLowerCase("tr").includes(term.toLocaleLowerCase("tr")));const visible=filtered.slice((page-1)*20,page*20);return <><section className="panel"><div className="panel-head"><div><h2>Varlık listesi</h2><p>{filtered.length} kayıt görüntüleniyor</p></div><div className="panel-actions"><button className="filter" onClick={()=>downloadCsv("varliklar",filtered)}>CSV dışa aktar</button><button className="primary" onClick={()=>setOpen(true)}><PackagePlus size={14}/> Yeni varlık</button></div></div><div className="search-row"><div className="search"><Search/><input aria-label="Varlık listesinde ara" placeholder="Kod, cihaz veya kategori ara…" value={term} onChange={e=>{setTerm(e.target.value);setPage(1)}}/></div></div>{visible.length===0?<Empty title="Bu kapsamda varlık bulunmuyor"/>:<div className="table-wrap"><table><thead><tr><th>Varlık kodu</th><th>Cihaz</th><th>Kategori</th><th>Konum</th><th>Durum</th></tr></thead><tbody>{visible.map(a=><tr key={a.code} className="clickable-row" onClick={()=>setSelected(a)}><td className="code">{a.code}</td><td><strong>{a.name}</strong><br/><small>{a.meta}</small></td><td>{a.category}</td><td>{a.place}</td><td><span className="badge gray">{statusLabel[a.status]??a.status}</span></td></tr>)}</tbody></table></div>}<Pagination page={page} total={filtered.length} onPage={setPage}/></section>{open&&<NewAssetDialog siteId={siteId} onClose={()=>setOpen(false)}/>} {selected&&<AssetDetailDialog siteId={siteId} summary={selected} assets={assets} onClose={()=>setSelected(undefined)}/>}</>}
function ActionPanel({siteId}:{siteId:string}){const [message,setMessage]=useState("Geliştirme AD dizinindeki kullanıcı ve bilgisayarları güvenli biçimde eşitleyin.");const [busy,setBusy]=useState(false);async function sync(){setBusy(true);const response=await fetch("/api/ad/sync",{method:"POST"});const payload=await response.json() as {data?:Record<string,number>;error?:{message?:string}};setBusy(false);setMessage(response.ok?`Tamamlandı: ${payload.data?.added??0} eklendi, ${payload.data?.updated??0} güncellendi, ${payload.data?.failed??0} hatalı.`:payload.error?.message??"Senkronizasyon başarısız.")}return <section className="panel"><div className="panel-head"><div><h2>AD senkronizasyonu</h2><p>objectGUID tabanlı idempotent kullanıcı ve bilgisayar aktarımı</p></div><button className="primary" onClick={sync} disabled={busy}><Activity size={14}/>{busy?"Senkronize ediliyor…":"Senkronizasyonu başlat"}</button></div><div className="empty-state"><ShieldCheck size={32}/><strong>{message}</strong><span>Seçili lokasyon: {siteId}</span></div></section>}
function Empty({title}:{title:string}){return <div className="empty-state"><Archive size={28}/><strong>{title}</strong></div>}
function Pagination({page,total,onPage}:{page:number;total:number;onPage:(page:number)=>void}){const pages=Math.max(1,Math.ceil(total/20));if(pages<=1)return null;return <div className="pagination"><button className="filter" disabled={page<=1} onClick={()=>onPage(page-1)}>Önceki</button><span>{page} / {pages}</span><button className="filter" disabled={page>=pages} onClick={()=>onPage(page+1)}>Sonraki</button></div>}
function formatCell(value:unknown){if(value===null||value===undefined||value==="")return "—";if(typeof value==="boolean")return value?"Aktif":"Pasif";if(typeof value==="string"&&/^\d{4}-\d{2}-\d{2}T/.test(value))return new Intl.DateTimeFormat("tr-TR",{dateStyle:"short",timeStyle:"short"}).format(new Date(value));if(typeof value==="object")return JSON.stringify(value);return String(value)}
const roleLabel:Record<string,string>={ADMIN:"Yönetici",IT_OPERATOR:"BT Operatörü",VIEWER:"Görüntüleyici",AUDITOR:"Denetçi"};function initials(name:string){return name.split(/\s+/).slice(0,2).map(part=>part[0]?.toLocaleUpperCase("tr")??"").join("")}
function canNavigate(role:string,label:string){const adminOnly=["Kullanıcı & Yetki","Sahip Şirketler","Ayarlar","Kabin Yönetimi"];const operatorOnly=["AD Senkronizasyonu","Eşleşmeyen AD"];if(adminOnly.includes(label))return role==="ADMIN";if(operatorOnly.includes(label))return role==="ADMIN"||role==="IT_OPERATOR";return true}
function downloadCsv<T extends object>(name:string,rows:ReadonlyArray<T>){if(!rows.length)return;const columns=[...new Set(rows.flatMap(row=>Object.keys(row)))];const escape=(value:unknown)=>`"${String(value??"").replaceAll('"','""')}"`;const content="\uFEFF"+[columns.map(escape).join(";"),...rows.map(row=>{const record=row as unknown as Record<string,unknown>;return columns.map(key=>escape(record[key])).join(";")})].join("\r\n");const url=URL.createObjectURL(new Blob([content],{type:"text/csv;charset=utf-8"}));const link=document.createElement("a");link.href=url;link.download=`${name.toLocaleLowerCase("tr").replace(/[^a-z0-9]+/g,"-")}.csv`;link.click();URL.revokeObjectURL(url)}

type Category={id:string;name:string;group:"OFFICE"|"NETWORK";formKind:"generic"|"computer"|"mobile"|"printer"|"network"};type Option={id:string;name:string};type Context={site:{id:string;provinceId:string};categories:Category[];companies:Option[];buildings:Array<Option&{siteId:string}>;floors:Array<Option&{buildingId:string}>;rooms:Array<Option&{floorId:string}>;racks:Array<Option&{roomId:string;shortCode:string}>};
function NewAssetDialog({siteId,onClose}:{siteId:string;onClose:()=>void}){
  const [context,setContext]=useState<Context>();
  const [people,setPeople]=useState<PersonOption[]>([]);
  const [categoryId,setCategoryId]=useState("");
  const [buildingId,setBuildingId]=useState("");
  const [floorId,setFloorId]=useState("");
  const [roomId,setRoomId]=useState("");
  const [message,setMessage]=useState("");
  const [busy,setBusy]=useState(false);

  useEffect(()=>{
    Promise.all([fetch(`/api/context?siteId=${siteId}`),fetch("/api/personnel")])
      .then(async([contextResponse,peopleResponse])=>{
        if(!contextResponse.ok||!peopleResponse.ok)throw new Error("Form verileri alınamadı");
        const contextPayload=await contextResponse.json() as {data?:Context};
        const peoplePayload=await peopleResponse.json() as {data?:PersonOption[]};
        if(contextPayload.data){
          setContext(contextPayload.data);
          setCategoryId(contextPayload.data.categories[0]?.id??"");
        }
        setPeople(peoplePayload.data??[]);
      })
      .catch(()=>setMessage("Form seçenekleri yüklenemedi."));
  },[siteId]);

  const category=context?.categories.find(item=>item.id===categoryId);
  const availableFloors=context?.floors.filter(item=>item.buildingId===buildingId)??[];
  const availableRooms=context?.rooms.filter(item=>item.floorId===floorId)??[];
  const availableRacks=context?.racks.filter(item=>!roomId||item.roomId===roomId)??[];

  async function submit(event:FormEvent<HTMLFormElement>){
    event.preventDefault();
    if(!context||!category)return;
    setBusy(true);
    setMessage("");
    const values=new FormData(event.currentTarget);
    const text=(key:string)=>String(values.get(key)??"").trim()||undefined;
    const integer=(key:string)=>{const value=text(key);return value?Number(value):undefined};
    const details=category.formKind==="network"
      ?{kind:"network",rackId:text("rackId"),rackUnit:integer("rackUnit"),ipAddress:text("ipAddress"),macAddress:text("macAddress"),managementAddress:text("managementAddress"),hostname:text("hostname"),installationPoint:text("installationPoint"),responsibleProfileId:text("responsibleProfileId")}
      :category.formKind==="computer"
        ?{kind:"computer",hostname:text("hostname"),operatingSystem:text("operatingSystem")}
        :category.formKind==="mobile"
          ?{kind:"mobile",imei1:text("imei1"),imei2:text("imei2"),phoneNumber:text("phoneNumber"),lineNumber:text("lineNumber"),operatingSystem:text("operatingSystem")}
          :category.formKind==="printer"
            ?{kind:"printer",ipAddress:text("ipAddress"),macAddress:text("macAddress"),printerName:text("printerName"),connectionType:text("connectionType"),isNetworkPrinter:Boolean(values.get("isNetworkPrinter"))}
            :{kind:"generic"};
    const response=await fetch("/api/assets",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({
      siteId,provinceId:context.site.provinceId,categoryId,ownerCompanyId:text("ownerCompanyId"),
      buildingId:text("buildingId"),floorId:text("floorId"),roomId:text("roomId"),
      name:text("name"),brand:text("brand"),model:text("model"),serialNumber:text("serialNumber"),
      inventoryNumber:text("inventoryNumber"),status:text("status")??"IN_STOCK",description:text("description"),details,
    })});
    const payload=await response.json() as {error?:{message?:string}};
    setBusy(false);
    if(!response.ok){setMessage(payload.error?.message??"Varlık kaydedilemedi.");return}
    window.location.reload();
  }

  return <div className="modal-backdrop" role="presentation"><div className="modal" role="dialog" aria-modal="true" aria-labelledby="asset-dialog-title">
    <div className="panel-head"><div><h2 id="asset-dialog-title">Yeni varlık</h2><p>Kategori ve fiziksel konuma göre dinamik alanlar</p></div><button className="icon-btn" onClick={onClose} aria-label="Kapat"><X size={16}/></button></div>
    {!context?<Empty title={message||"Form hazırlanıyor…"}/>:<form onSubmit={submit} className="form-grid">
      <label>Kategori<select value={categoryId} onChange={event=>setCategoryId(event.target.value)} required>{context.categories.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label>
      <label>Sahip şirket<select name="ownerCompanyId" required><option value="">Seçin</option>{context.companies.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label>
      <label>Bina<select name="buildingId" value={buildingId} onChange={event=>{setBuildingId(event.target.value);setFloorId("");setRoomId("")}}><option value="">Seçin</option>{context.buildings.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label>
      <label>Kat<select name="floorId" value={floorId} onChange={event=>{setFloorId(event.target.value);setRoomId("")}} disabled={!buildingId}><option value="">Seçin</option>{availableFloors.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label>
      <label>Oda / Bölüm<select name="roomId" value={roomId} onChange={event=>setRoomId(event.target.value)} disabled={!floorId}><option value="">Seçin</option>{availableRooms.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label>
      <label className="wide">Cihaz adı<input name="name" required minLength={2}/></label>
      <label>Marka<input name="brand"/></label><label>Model<input name="model"/></label>
      <label>Seri numarası<input name="serialNumber"/></label><label>Demirbaş numarası<input name="inventoryNumber"/></label>
      <label>Durum<select name="status" defaultValue="IN_STOCK">{Object.entries(statusLabel).map(([value,label])=><option key={value} value={value}>{label}</option>)}</select></label>
      {category?.formKind==="network"&&<>
        <label>Kabin<select name="rackId" required><option value="">Seçin</option>{availableRacks.map(item=><option key={item.id} value={item.id}>{item.name} · {item.shortCode}</option>)}</select></label>
        <label>Kabin U konumu<input name="rackUnit" type="number" min={1} max={100}/></label>
        <label>IP adresi<input name="ipAddress" placeholder="10.0.0.10"/></label><label>MAC adresi<input name="macAddress" placeholder="00:11:22:33:44:55"/></label>
        <label>Yönetim adresi<input name="managementAddress"/></label><label>Hostname<input name="hostname"/></label>
        <label>Sorumlu personel<select name="responsibleProfileId"><option value="">Seçin</option>{people.map(person=><option key={person.id} value={person.id}>{person.displayName}</option>)}</select></label>
        <label>Kurulum noktası<input name="installationPoint"/></label>
      </>}
      {category?.formKind==="computer"&&<><label>Hostname<input name="hostname"/></label><label>İşletim sistemi<input name="operatingSystem"/></label></>}
      {category?.formKind==="mobile"&&<>
        <label>IMEI 1<input name="imei1" inputMode="numeric" minLength={15} maxLength={15}/></label><label>IMEI 2<input name="imei2" inputMode="numeric" minLength={15} maxLength={15}/></label>
        <label>Telefon numarası<input name="phoneNumber"/></label><label>Hat numarası<input name="lineNumber"/></label><label>İşletim sistemi<input name="operatingSystem"/></label>
      </>}
      {category?.formKind==="printer"&&<>
        <label>IP adresi<input name="ipAddress"/></label><label>MAC adresi<input name="macAddress" placeholder="00:11:22:33:44:55"/></label>
        <label>Yazıcı adı<input name="printerName"/></label><label>Bağlantı türü<input name="connectionType"/></label>
        <label className="check"><input type="checkbox" name="isNetworkPrinter"/> Ağ yazıcısı</label>
      </>}
      <label className="wide">Açıklama<textarea name="description" rows={3}/></label>
      {message&&<p className="form-error wide">{message}</p>}
      <div className="form-actions wide"><button type="button" className="filter" onClick={onClose}>Vazgeç</button><button className="primary" disabled={busy}>{busy?"Kaydediliyor…":"Varlığı kaydet"}</button></div>
    </form>}
  </div></div>;
}

type PersonOption={id:string;username?:string;displayName:string;department:string|null};
function RecordDialog({kind,siteId,assets,onClose}:{kind:"assignment"|"phone";siteId:string;assets:AssetView[];onClose:()=>void}){const [people,setPeople]=useState<PersonOption[]>([]);const [busy,setBusy]=useState(false);const [message,setMessage]=useState("");useEffect(()=>{fetch("/api/personnel").then(r=>r.json()).then((p:{data?:PersonOption[]})=>setPeople(p.data??[])).catch(()=>setMessage("Personel listesi alınamadı."))},[]);const eligible=kind==="phone"?assets.filter(a=>a.category.toLocaleLowerCase("tr").includes("telefon")):assets.filter(a=>a.group==="OFFICE");async function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();const data=new FormData(event.currentTarget);const value=(key:string)=>String(data.get(key)??"").trim();const body=kind==="assignment"?{siteId,assetId:value("assetId"),profileId:value("profileId"),assignedAt:value("date")||undefined,notes:value("notes")||undefined}:{siteId,assetId:value("assetId"),profileId:value("profileId"),extension:value("extension")||undefined,phoneNumber:value("phoneNumber")||undefined,startDate:value("date"),notes:value("notes")||undefined,isPrimary:true};setBusy(true);const response=await fetch(kind==="assignment"?"/api/assignments":"/api/phone-users",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(body)});const payload=await response.json() as {error?:{message?:string}};setBusy(false);if(!response.ok){setMessage(payload.error?.message??"Kayıt oluşturulamadı.");return}window.location.reload()}const today=new Date().toISOString().slice(0,10);return <div className="modal-backdrop"><div className="modal" role="dialog" aria-modal="true"><div className="panel-head"><div><h2>{kind==="assignment"?"Yeni zimmet":"Telefon kullanıcısı ata"}</h2><p>Geçmiş kayıtları korunarak yeni işlem oluşturulur</p></div><button className="icon-btn" onClick={onClose} aria-label="Kapat"><X size={16}/></button></div><form className="form-grid" onSubmit={submit}><label className="wide">Varlık<select name="assetId" required><option value="">Seçin</option>{eligible.map(a=><option key={a.id} value={a.id}>{a.code} · {a.name}</option>)}</select></label><label className="wide">Personel<select name="profileId" required><option value="">Seçin</option>{people.map(p=><option key={p.id} value={p.id}>{p.displayName}{p.department?` · ${p.department}`:""}</option>)}</select></label><label>{kind==="assignment"?"Zimmet tarihi":"Başlangıç tarihi"}<input type="date" name="date" defaultValue={today} required/></label>{kind==="phone"&&<><label>Dahili numara<input name="extension"/></label><label>Telefon numarası<input name="phoneNumber"/></label></>}<label className="wide">Açıklama<textarea name="notes" rows={3}/></label>{message&&<p className="form-error wide">{message}</p>}<div className="form-actions wide"><button type="button" className="filter" onClick={onClose}>Vazgeç</button><button className="primary" disabled={busy}>{busy?"Kaydediliyor…":"Kaydet"}</button></div></form></div></div>}

type AssetDetail={asset:{id:string;name:string;assetCode:string;status:string;description:string|null};details:RemoteRow|null;relations:Array<{id:string;type:string;sourceAssetId:string;targetAssetId:string}>;movements:Array<{id:string;type:string;oldAssetCode:string|null;newAssetCode:string|null;createdAt:string}>};
const detailFieldLabel:Record<string,string>={hostname:"Hostname",operatingSystem:"İşletim sistemi",adObjectGuid:"AD nesne GUID",adDistinguishedName:"AD distinguished name",lastAdSyncAt:"Son AD senkronizasyonu",imei1:"IMEI 1",imei2:"IMEI 2",phoneNumber:"Telefon numarası",lineNumber:"Hat numarası",lastUserChangeAt:"Son kullanıcı değişikliği",ipAddress:"IP adresi",macAddress:"MAC adresi",printerName:"Yazıcı adı",connectionType:"Bağlantı türü",isNetworkPrinter:"Ağ yazıcısı",rackUnit:"Kabin U konumu",managementAddress:"Yönetim adresi",installationPoint:"Kurulum noktası",rackName:"Kabin",responsibleProfileName:"Sorumlu personel"};
const relationLabel:Record<string,string>={CONNECTED_TO:"Bağlı",INSTALLED_IN:"Kurulu",POWERED_BY:"Besleniyor",RECORDED_BY:"Kaydediliyor",PARENT_OF:"Üst cihaz",ACCESSORY_OF:"Aksesuar"};
const movementLabel:Record<string,string>={RACK_CHANGED:"Kabin değişikliği",SITE_CHANGED:"Lokasyon değişikliği",STATUS_CHANGED:"Durum değişikliği"};
function AssetDetailDialog({siteId,summary,assets,onClose}:{siteId:string;summary:AssetView;assets:AssetView[];onClose:()=>void}){const [detail,setDetail]=useState<AssetDetail>();const [message,setMessage]=useState("");const [busy,setBusy]=useState(false);useEffect(()=>{fetch(`/api/assets/${summary.id}?siteId=${siteId}`).then(r=>r.json()).then((p:{data?:AssetDetail;error?:{message?:string}})=>p.data?setDetail(p.data):setMessage(p.error?.message??"Detay alınamadı.")).catch(()=>setMessage("Detay alınamadı."))},[siteId,summary.id]);async function save(event:FormEvent<HTMLFormElement>){event.preventDefault();const data=new FormData(event.currentTarget);setBusy(true);const response=await fetch(`/api/assets/${summary.id}`,{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({siteId,name:String(data.get("name")??""),status:String(data.get("status")??""),description:String(data.get("description")??"")||undefined})});const payload=await response.json() as {error?:{message?:string}};setBusy(false);if(!response.ok){setMessage(payload.error?.message??"Güncelleme başarısız.");return}window.location.reload()}async function addRelation(event:FormEvent<HTMLFormElement>){event.preventDefault();const data=new FormData(event.currentTarget);const response=await fetch(`/api/assets/${summary.id}/relations`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({siteId,targetAssetId:String(data.get("targetAssetId")),type:String(data.get("type"))})});const payload=await response.json() as {data?:AssetDetail["relations"][number];error?:{message?:string}};if(!response.ok){setMessage(payload.error?.message??"Bağlantı kurulamadı.");return}if(payload.data)setDetail(current=>current?{...current,relations:[...current.relations,payload.data!]}:current)}return <div className="modal-backdrop"><div className="modal modal-wide" role="dialog" aria-modal="true"><div className="panel-head"><div><h2>{summary.name}</h2><p className="code">{summary.code}</p></div><button className="icon-btn" onClick={onClose} aria-label="Kapat"><X size={16}/></button></div>{!detail?<Empty title={message||"Varlık detayları yükleniyor…"}/>:<><form className="form-grid" onSubmit={save}><label className="wide">Cihaz adı<input name="name" defaultValue={detail.asset.name} required/></label><label>Durum<select name="status" defaultValue={detail.asset.status}>{Object.entries(statusLabel).map(([value,label])=><option key={value} value={value}>{label}</option>)}</select></label><label className="wide">Açıklama<textarea name="description" rows={3} defaultValue={detail.asset.description??""}/></label>{detail.details&&<div className="detail-box wide">{Object.entries(detail.details).filter(([key,value])=>!key.endsWith("Id")&&value!==null&&value!==undefined&&value!=="").map(([key,value])=><span key={key}><small>{detailFieldLabel[key]??key}</small><strong>{formatCell(value)}</strong></span>)}</div>} {message&&<p className="form-error wide">{message}</p>}<div className="form-actions wide"><button type="button" className="filter" onClick={onClose}>Kapat</button><button className="primary" disabled={busy}>{busy?"Güncelleniyor…":"Değişiklikleri kaydet"}</button></div></form><div className="subsection"><h3>Cihaz bağlantıları</h3><form className="inline-form" onSubmit={addRelation}><select name="targetAssetId" required><option value="">Bağlanacak varlık</option>{assets.filter(a=>a.id!==summary.id).map(a=><option key={a.id} value={a.id}>{a.code} · {a.name}</option>)}</select><select name="type"><option value="CONNECTED_TO">Bağlı</option><option value="INSTALLED_IN">Kurulu</option><option value="POWERED_BY">Besleniyor</option><option value="RECORDED_BY">Kaydediliyor</option><option value="PARENT_OF">Üst cihaz</option><option value="ACCESSORY_OF">Aksesuar</option></select><button className="primary">Bağlantı ekle</button></form>{detail.relations.length===0?<p className="muted-text">Bağlantı bulunmuyor.</p>:<ul className="relation-list">{detail.relations.map(r=>{const relatedId=r.sourceAssetId===summary.id?r.targetAssetId:r.sourceAssetId;const related=assets.find(asset=>asset.id===relatedId);return <li key={r.id}><span className="badge gray">{relationLabel[r.type]??r.type}</span><span className="code">{related?`${related.code} · ${related.name}`:relatedId}</span></li>})}</ul>}</div><div className="subsection"><h3>Hareket geçmişi</h3>{detail.movements.length===0?<p className="muted-text">Henüz hareket kaydı yok.</p>:<ul className="relation-list">{detail.movements.map(m=><li key={m.id}><span>{movementLabel[m.type]??m.type}<small> · {formatCell(m.createdAt)}</small></span><span className="code">{m.oldAssetCode??"—"} → {m.newAssetCode??"—"}</span></li>)}</ul>}</div></>}</div></div>}

type UserScope={type:"GLOBAL"|"PROVINCE"|"SITE";provinceId:string|null;siteId:string|null};type ManagedUser={id:string;username:string;displayName:string;email:string|null;role:string;isActive:boolean;scopes:UserScope[]};type LocationOption={id:string;name:string};type AdminLocations={provinces:LocationOption[];sites:Array<LocationOption&{provinceId:string}>};
function UserAccessPanel(){const [users,setUsers]=useState<ManagedUser[]>([]);const [profiles,setProfiles]=useState<PersonOption[]>([]);const [locations,setLocations]=useState<AdminLocations>({provinces:[],sites:[]});const [open,setOpen]=useState(false);const [selected,setSelected]=useState<ManagedUser>();const [message,setMessage]=useState("");async function load(){try{const [u,p,l]=await Promise.all([fetch("/api/admin/users"),fetch("/api/personnel"),fetch("/api/admin/locations")]);const uj=await u.json() as {data?:unknown};const pj=await p.json() as {data?:unknown};const lj=await l.json() as {data?:unknown};setUsers(Array.isArray(uj.data)?uj.data as ManagedUser[]:[]);setProfiles(Array.isArray(pj.data)?pj.data as PersonOption[]:[]);if(lj.data&&typeof lj.data==="object")setLocations(lj.data as AdminLocations)}catch{setMessage("Yetki kayıtları alınamadı.")}}useEffect(()=>{const timer=window.setTimeout(()=>void load(),0);return()=>window.clearTimeout(timer)},[]);async function toggle(user:ManagedUser){const response=await fetch(`/api/admin/users/${user.id}`,{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({isActive:!user.isActive})});if(response.ok)setUsers(current=>current.map(item=>item.id===user.id?{...item,isActive:!item.isActive}:item))}return <><section className="panel"><div className="panel-head"><div><h2>Kullanıcı, rol ve kapsam yönetimi</h2><p>{users.length} uygulama hesabı</p></div><button className="primary" onClick={()=>setOpen(true)}><UserCog size={14}/> Erişim hesabı ekle</button></div>{message&&<p className="form-error" style={{padding:16}}>{message}</p>}<div className="table-wrap"><table><thead><tr><th>Kullanıcı</th><th>Rol</th><th>Kapsam</th><th>Durum</th><th>İşlem</th></tr></thead><tbody>{users.map(user=><tr key={user.id}><td><strong>{user.displayName}</strong><br/><small>{user.username}</small></td><td>{roleLabel[user.role]??user.role}</td><td>{user.scopes.map(scope=>scope.type==="GLOBAL"?"Tüm lokasyonlar":scope.type==="PROVINCE"?`İl: ${locations.provinces.find(p=>p.id===scope.provinceId)?.name??scope.provinceId}`:`Lokasyon: ${locations.sites.find(s=>s.id===scope.siteId)?.name??scope.siteId}`).join(", ")}</td><td><span className={`badge ${user.isActive?"green":"gray"}`}>{user.isActive?"Aktif":"Pasif"}</span></td><td><button className="link-button" onClick={()=>setSelected(user)}>Yetki düzenle</button><button className="link-button" onClick={()=>toggle(user)}>{user.isActive?"Pasife al":"Aktifleştir"}</button></td></tr>)}</tbody></table></div></section>{open&&<UserAccessDialog profiles={profiles.filter(profile=>!users.some(user=>user.username===profile.username))} locations={locations} onClose={()=>setOpen(false)}/>} {selected&&<UserEditDialog user={selected} locations={locations} onClose={()=>setSelected(undefined)}/>}</>}
function UserAccessDialog({profiles,locations,onClose}:{profiles:PersonOption[];locations:AdminLocations;onClose:()=>void}){const [scopeType,setScopeType]=useState<"GLOBAL"|"PROVINCE"|"SITE">("SITE");const [message,setMessage]=useState("");const [busy,setBusy]=useState(false);async function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();const data=new FormData(event.currentTarget);const scope={type:scopeType,provinceId:scopeType==="PROVINCE"?String(data.get("scopeId")):undefined,siteId:scopeType==="SITE"?String(data.get("scopeId")):undefined};setBusy(true);const response=await fetch("/api/admin/users",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({adProfileId:String(data.get("profileId")),role:String(data.get("role")),password:String(data.get("password")),scopes:[scope]})});const payload=await response.json() as {error?:{message?:string}};setBusy(false);if(!response.ok){setMessage(payload.error?.message??"Hesap oluşturulamadı.");return}window.location.reload()}const options=scopeType==="PROVINCE"?locations.provinces:locations.sites;return <div className="modal-backdrop"><div className="modal" role="dialog" aria-modal="true"><div className="panel-head"><div><h2>Erişim hesabı oluştur</h2><p>AD profili erişim hesabından ayrı tutulur</p></div><button className="icon-btn" onClick={onClose} aria-label="Kapat"><X size={16}/></button></div><form className="form-grid" onSubmit={submit}><label className="wide">AD personeli<select name="profileId" required><option value="">Seçin</option>{profiles.map(profile=><option key={profile.id} value={profile.id}>{profile.displayName}{profile.department?` · ${profile.department}`:""}</option>)}</select></label><label>Rol<select name="role" defaultValue="VIEWER"><option value="ADMIN">Yönetici</option><option value="IT_OPERATOR">BT Operatörü</option><option value="VIEWER">Görüntüleyici</option><option value="AUDITOR">Denetçi</option></select></label><label>Geçici parola<input name="password" type="password" minLength={10} required/></label><label>Kapsam türü<select value={scopeType} onChange={e=>setScopeType(e.target.value as typeof scopeType)}><option value="GLOBAL">Global</option><option value="PROVINCE">İl</option><option value="SITE">Lokasyon</option></select></label>{scopeType!=="GLOBAL"&&<label>Kapsam<select name="scopeId" required><option value="">Seçin</option>{options.map(option=><option key={option.id} value={option.id}>{option.name}</option>)}</select></label>}{message&&<p className="form-error wide">{message}</p>}<div className="form-actions wide"><button type="button" className="filter" onClick={onClose}>Vazgeç</button><button className="primary" disabled={busy}>{busy?"Oluşturuluyor…":"Hesabı oluştur"}</button></div></form></div></div>}
function UserEditDialog({user,locations,onClose}:{user:ManagedUser;locations:AdminLocations;onClose:()=>void}){const first=user.scopes[0];const [scopeType,setScopeType]=useState<"GLOBAL"|"PROVINCE"|"SITE">(first?.type??"SITE");const [message,setMessage]=useState("");async function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();const data=new FormData(event.currentTarget);const id=String(data.get("scopeId")??"");const scope={type:scopeType,provinceId:scopeType==="PROVINCE"?id||undefined:undefined,siteId:scopeType==="SITE"?id||undefined:undefined};const password=String(data.get("password")??"")||undefined;const response=await fetch(`/api/admin/users/${user.id}`,{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({role:String(data.get("role")),password,scopes:[scope]})});if(response.ok){window.location.reload();return}const payload=await response.json() as {error?:{message?:string}};setMessage(payload.error?.message??"Yetkiler güncellenemedi.")}const options=scopeType==="PROVINCE"?locations.provinces:locations.sites;const defaultScope=scopeType==="PROVINCE"?first?.provinceId??"":scopeType==="SITE"?first?.siteId??"":"";return <div className="modal-backdrop"><div className="modal" role="dialog" aria-modal="true"><div className="panel-head"><div><h2>{user.displayName}</h2><p>Rol ve erişim kapsamını güncelle</p></div><button className="icon-btn" aria-label="Kapat" onClick={onClose}><X size={16}/></button></div><form className="form-grid" onSubmit={submit}><label>Rol<select name="role" defaultValue={user.role}><option value="ADMIN">Yönetici</option><option value="IT_OPERATOR">BT Operatörü</option><option value="VIEWER">Görüntüleyici</option><option value="AUDITOR">Denetçi</option></select></label><label>Yeni parola (isteğe bağlı)<input name="password" type="password" minLength={10}/></label><label>Kapsam türü<select value={scopeType} onChange={e=>setScopeType(e.target.value as typeof scopeType)}><option value="GLOBAL">Global</option><option value="PROVINCE">İl</option><option value="SITE">Lokasyon</option></select></label>{scopeType!=="GLOBAL"&&<label>Kapsam<select key={`${scopeType}-${defaultScope}`} name="scopeId" defaultValue={defaultScope} required><option value="">Seçin</option>{options.map(option=><option key={option.id} value={option.id}>{option.name}</option>)}</select></label>}{message&&<p className="form-error wide">{message}</p>}<div className="form-actions wide"><button type="button" className="filter" onClick={onClose}>Vazgeç</button><button className="primary">Yetkileri güncelle</button></div></form></div></div>}

type ManagedCategory={id:string;group:"OFFICE"|"NETWORK";name:string;slug:string;code:string|null;formKind:string;isAssignable:boolean;isActive:boolean};
function CategoryAdminPanel(){const [items,setItems]=useState<ManagedCategory[]>([]);const [open,setOpen]=useState(false);const [message,setMessage]=useState("");useEffect(()=>{fetch("/api/admin/categories").then(r=>r.json()).then((p:{data?:ManagedCategory[]})=>setItems(p.data??[])).catch(()=>setMessage("Kategoriler alınamadı."))},[]);async function toggle(item:ManagedCategory){const response=await fetch(`/api/admin/categories/${item.id}`,{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({isActive:!item.isActive})});if(response.ok)setItems(current=>current.map(row=>row.id===item.id?{...row,isActive:!row.isActive}:row))}return <><section className="panel"><div className="panel-head"><div><h2>Kategori ve kod yönetimi</h2><p>{items.length} dinamik kategori</p></div><button className="primary" onClick={()=>setOpen(true)}><PackagePlus size={14}/> Kategori ekle</button></div>{message&&<p className="form-error" style={{padding:16}}>{message}</p>}<div className="table-wrap"><table><thead><tr><th>Ana grup</th><th>Kategori</th><th>Kod</th><th>Dinamik form</th><th>Zimmet</th><th>Durum</th><th>İşlem</th></tr></thead><tbody>{items.map(item=><tr key={item.id}><td>{item.group==="OFFICE"?"Kullanıcı / Ofis":"Ağ / Altyapı"}</td><td>{item.name}</td><td className="code">{item.code??"—"}</td><td>{item.formKind}</td><td>{item.isAssignable?"Evet":"Hayır"}</td><td><span className={`badge ${item.isActive?"green":"gray"}`}>{item.isActive?"Aktif":"Pasif"}</span></td><td><button className="link-button" onClick={()=>toggle(item)}>{item.isActive?"Pasife al":"Aktifleştir"}</button></td></tr>)}</tbody></table></div></section>{open&&<CategoryDialog onClose={()=>setOpen(false)}/>}</>}
function CategoryDialog({onClose}:{onClose:()=>void}){const [message,setMessage]=useState("");const [busy,setBusy]=useState(false);async function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();const data=new FormData(event.currentTarget);const body={group:String(data.get("group")),name:String(data.get("name")),slug:String(data.get("slug")),code:String(data.get("code")??"")||undefined,formKind:String(data.get("formKind")),isAssignable:Boolean(data.get("isAssignable"))};setBusy(true);const response=await fetch("/api/admin/categories",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(body)});const payload=await response.json() as {error?:{message?:string}};setBusy(false);if(!response.ok){setMessage(payload.error?.message??"Kategori oluşturulamadı.");return}window.location.reload()}return <div className="modal-backdrop"><div className="modal" role="dialog" aria-modal="true"><div className="panel-head"><div><h2>Yeni kategori</h2><p>Kod değişikliği gerektirmeden yeni cihaz türü ekleyin</p></div><button className="icon-btn" aria-label="Kapat" onClick={onClose}><X size={16}/></button></div><form className="form-grid" onSubmit={submit}><label>Ana grup<select name="group"><option value="OFFICE">Kullanıcı / Ofis</option><option value="NETWORK">Ağ / Altyapı</option></select></label><label>Form türü<select name="formKind"><option value="generic">Genel</option><option value="computer">Bilgisayar</option><option value="mobile">Mobil</option><option value="printer">Yazıcı</option><option value="network">Ağ cihazı</option></select></label><label>Kategori adı<input name="name" required/></label><label>Slug<input name="slug" pattern="[a-z0-9-]+" required/></label><label>Kategori kodu<input name="code" maxLength={20}/></label><label className="check"><input type="checkbox" name="isAssignable"/> Zimmetlenebilir</label>{message&&<p className="form-error wide">{message}</p>}<div className="form-actions wide"><button type="button" className="filter" onClick={onClose}>Vazgeç</button><button className="primary" disabled={busy}>{busy?"Kaydediliyor…":"Kategori ekle"}</button></div></form></div></div>}

type EntityType="province"|"site"|"building"|"floor"|"room"|"rack";
type HierarchyData={provinces:Array<LocationOption&{code:string;isActive:boolean}>;sites:Array<LocationOption&{provinceId:string;code:string;isActive:boolean}>;buildings:Array<LocationOption&{siteId:string;code:string;isActive:boolean}>;floors:Array<LocationOption&{buildingId:string;code:string;isActive:boolean}>;rooms:Array<LocationOption&{floorId:string;code:string;isActive:boolean}>;racks:Array<LocationOption&{siteId:string;roomId:string;number:string;shortCode:string;isActive:boolean}>};
function LocationAdminPanel(){
  const [data,setData]=useState<HierarchyData>({provinces:[],sites:[],buildings:[],floors:[],rooms:[],racks:[]});
  const [open,setOpen]=useState(false);
  const [message,setMessage]=useState("");
  useEffect(()=>{fetch("/api/admin/locations").then(response=>response.json()).then((payload:{data?:HierarchyData})=>setData(current=>payload.data??current)).catch(()=>setMessage("Lokasyon hiyerarşisi alınamadı."))},[]);
  const rows=[
    ...data.provinces.map(item=>({...item,entity:"province" as const,type:"İl",parent:"—"})),
    ...data.sites.map(item=>({...item,entity:"site" as const,type:"Lokasyon",parent:data.provinces.find(parent=>parent.id===item.provinceId)?.name??"—"})),
    ...data.buildings.map(item=>({...item,entity:"building" as const,type:"Bina",parent:data.sites.find(parent=>parent.id===item.siteId)?.name??"—"})),
    ...data.floors.map(item=>({...item,entity:"floor" as const,type:"Kat",parent:data.buildings.find(parent=>parent.id===item.buildingId)?.name??"—"})),
    ...data.rooms.map(item=>({...item,entity:"room" as const,type:"Oda",parent:data.floors.find(parent=>parent.id===item.floorId)?.name??"—"})),
    ...data.racks.map(item=>({...item,entity:"rack" as const,type:"Kabin",code:item.shortCode,parent:data.rooms.find(parent=>parent.id===item.roomId)?.name??"—"})),
  ];
  async function toggle(row:{id:string;entity:EntityType;isActive:boolean}){
    setMessage("");
    const response=await fetch("/api/admin/locations",{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({entity:row.entity,id:row.id,isActive:!row.isActive})});
    if(response.ok){window.location.reload();return}
    const payload=await response.json() as {error?:{message?:string}};
    setMessage(payload.error?.message??"Lokasyon durumu güncellenemedi.");
  }
  return <><section className="panel">
    <div className="panel-head"><div><h2>Fiziksel lokasyon ve kabin yönetimi</h2><p>{rows.length} hiyerarşi kaydı</p></div><button className="primary" onClick={()=>setOpen(true)}><Building2 size={14}/> Kayıt ekle</button></div>
    {message&&<p className="form-error" style={{padding:16}}>{message}</p>}
    <div className="table-wrap"><table><thead><tr><th>Tür</th><th>Ad</th><th>Kod</th><th>Üst kayıt</th><th>Durum</th><th>İşlem</th></tr></thead><tbody>{rows.map(row=><tr key={`${row.entity}-${row.id}`}><td>{row.type}</td><td>{row.name}</td><td className="code">{row.code}</td><td>{row.parent}</td><td><span className={`badge ${row.isActive?"green":"gray"}`}>{row.isActive?"Aktif":"Pasif"}</span></td><td><button className="link-button" onClick={()=>toggle(row)}>{row.isActive?"Pasife al":"Aktifleştir"}</button></td></tr>)}</tbody></table></div>
  </section>{open&&<LocationDialog data={data} onClose={()=>setOpen(false)}/>}</>;
}
function LocationDialog({data,onClose}:{data:HierarchyData;onClose:()=>void}){const [entity,setEntity]=useState<EntityType>("rack");const [message,setMessage]=useState("");const [busy,setBusy]=useState(false);async function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();const form=new FormData(event.currentTarget);const value=(key:string)=>String(form.get(key)??"").trim()||undefined;const body:Record<string,unknown>={entity,name:value("name")};if(entity!=="rack")body.code=value("code");if(entity==="site")body.provinceId=value("parentId");if(entity==="building")body.siteId=value("parentId");if(entity==="floor")body.buildingId=value("parentId");if(entity==="room")body.floorId=value("parentId");if(entity==="rack"){body.siteId=value("siteId");body.roomId=value("parentId");body.number=value("number");body.shortCode=value("code");body.description=value("description")}setBusy(true);const response=await fetch("/api/admin/locations",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(body)});const payload=await response.json() as {error?:{message?:string}};setBusy(false);if(!response.ok){setMessage(payload.error?.message??"Kayıt oluşturulamadı.");return}window.location.reload()}const parents=entity==="site"?data.provinces:entity==="building"?data.sites:entity==="floor"?data.buildings:entity==="room"?data.floors:entity==="rack"?data.rooms:[];return <div className="modal-backdrop"><div className="modal" role="dialog" aria-modal="true"><div className="panel-head"><div><h2>Hiyerarşi kaydı ekle</h2><p>İl → Lokasyon → Bina → Kat → Oda → Kabin</p></div><button className="icon-btn" aria-label="Kapat" onClick={onClose}><X size={16}/></button></div><form className="form-grid" onSubmit={submit}><label>Kayıt türü<select value={entity} onChange={e=>setEntity(e.target.value as EntityType)}><option value="province">İl</option><option value="site">Lokasyon</option><option value="building">Bina</option><option value="floor">Kat</option><option value="room">Oda / Bölüm</option><option value="rack">Kabin</option></select></label>{entity!=="province"&&<label>Üst kayıt<select name="parentId" required><option value="">Seçin</option>{parents.map(parent=><option key={parent.id} value={parent.id}>{parent.name}</option>)}</select></label>}{entity==="rack"&&<label>Lokasyon<select name="siteId" required><option value="">Seçin</option>{data.sites.map(site=><option key={site.id} value={site.id}>{site.name}</option>)}</select></label>}<label>Ad<input name="name" required/></label><label>{entity==="rack"?"Kısa kod":"Kod"}<input name="code" required/></label>{entity==="rack"&&<><label>Kabin numarası<input name="number" required/></label><label className="wide">Açıklama<textarea name="description"/></label></>}{message&&<p className="form-error wide">{message}</p>}<div className="form-actions wide"><button type="button" className="filter" onClick={onClose}>Vazgeç</button><button className="primary" disabled={busy}>{busy?"Kaydediliyor…":"Kaydet"}</button></div></form></div></div>}

type UnmatchedRecord={id:string;name:string;distinguishedName:string;reason:string;firstSeenAt:string};
function AdUnmatchedPanel(){const [records,setRecords]=useState<UnmatchedRecord[]>([]);const [sites,setSites]=useState<LocationOption[]>([]);const [selection,setSelection]=useState<Record<string,string>>({});const [message,setMessage]=useState("");useEffect(()=>{Promise.all([fetch("/api/ad/unmatched"),fetch("/api/admin/locations")]).then(async([a,l])=>{const ad=await a.json() as {data?:UnmatchedRecord[]};const locations=await l.json() as {data?:AdminLocations};setRecords(ad.data??[]);setSites(locations.data?.sites??[])}).catch(()=>setMessage("Eşleştirilmemiş AD kayıtları alınamadı."))},[]);async function map(record:UnmatchedRecord){const siteId=selection[record.id];if(!siteId){setMessage("Önce lokasyon seçin.");return}const response=await fetch("/api/ad/unmatched",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({recordId:record.id,siteId})});if(response.ok){setRecords(current=>current.filter(item=>item.id!==record.id));setMessage("OU eşleştirmesi kaydedildi. Sonraki senkronizasyonda bilgisayar oluşturulacak.")}else{const payload=await response.json() as {error?:{message?:string}};setMessage(payload.error?.message??"Eşleştirme başarısız.")}}return <section className="panel"><div className="panel-head"><div><h2>Eşleştirilmemiş AD bilgisayarları</h2><p>{records.length} kayıt lokasyon eşleştirmesi bekliyor</p></div></div>{message&&<p className="muted-text" style={{padding:"0 18px"}}>{message}</p>}{records.length===0?<Empty title="Eşleştirilmemiş AD kaydı bulunmuyor"/>:<div className="table-wrap"><table><thead><tr><th>Bilgisayar</th><th>Distinguished name</th><th>Neden</th><th>Lokasyon</th><th>İşlem</th></tr></thead><tbody>{records.map(record=><tr key={record.id}><td><strong>{record.name}</strong><br/><small>{formatCell(record.firstSeenAt)}</small></td><td className="code">{record.distinguishedName}</td><td>{record.reason}</td><td><select className="filter" value={selection[record.id]??""} onChange={e=>setSelection(current=>({...current,[record.id]:e.target.value}))}><option value="">Seçin</option>{sites.map(site=><option key={site.id} value={site.id}>{site.name}</option>)}</select></td><td><button className="link-button" onClick={()=>map(record)}>Eşleştir</button></td></tr>)}</tbody></table></div>}</section>}

type Company={id:string;name:string;code:string;isActive:boolean};
function CompanyAdminPanel(){const [companies,setCompanies]=useState<Company[]>([]);const [open,setOpen]=useState(false);useEffect(()=>{fetch("/api/admin/companies").then(r=>r.json()).then((p:{data?:Company[]})=>setCompanies(p.data??[])).catch(()=>undefined)},[]);async function toggle(company:Company){const response=await fetch(`/api/admin/companies/${company.id}`,{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({isActive:!company.isActive})});if(response.ok)setCompanies(current=>current.map(item=>item.id===company.id?{...item,isActive:!item.isActive}:item))}return <><section className="panel"><div className="panel-head"><div><h2>Sahip şirketler</h2><p>Fiziksel lokasyondan bağımsız varlık sahipliği</p></div><button className="primary" onClick={()=>setOpen(true)}><Building2 size={14}/> Şirket ekle</button></div><div className="table-wrap"><table><thead><tr><th>Şirket</th><th>Kod</th><th>Durum</th><th>İşlem</th></tr></thead><tbody>{companies.map(company=><tr key={company.id}><td>{company.name}</td><td className="code">{company.code}</td><td><span className={`badge ${company.isActive?"green":"gray"}`}>{company.isActive?"Aktif":"Pasif"}</span></td><td><button className="link-button" onClick={()=>toggle(company)}>{company.isActive?"Pasife al":"Aktifleştir"}</button></td></tr>)}</tbody></table></div></section>{open&&<CompanyDialog onClose={()=>setOpen(false)}/>}</>}
function CompanyDialog({onClose}:{onClose:()=>void}){const [message,setMessage]=useState("");async function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();const data=new FormData(event.currentTarget);const response=await fetch("/api/admin/companies",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({name:String(data.get("name")),code:String(data.get("code"))})});if(response.ok){window.location.reload();return}const payload=await response.json() as {error?:{message?:string}};setMessage(payload.error?.message??"Şirket oluşturulamadı.")}return <div className="modal-backdrop"><div className="modal" role="dialog" aria-modal="true"><div className="panel-head"><div><h2>Sahip şirket ekle</h2><p>Varlığın sahibi fiziksel lokasyondan bağımsızdır</p></div><button className="icon-btn" aria-label="Kapat" onClick={onClose}><X size={16}/></button></div><form className="form-grid" onSubmit={submit}><label className="wide">Şirket adı<input name="name" required/></label><label>Şirket kodu<input name="code" required/></label>{message&&<p className="form-error wide">{message}</p>}<div className="form-actions wide"><button type="button" className="filter" onClick={onClose}>Vazgeç</button><button className="primary">Şirket ekle</button></div></form></div></div>}
